(function($) {
'use strict';
function debounce(func, wait) {
var timeout;
return function() {
var context = this;
var args = arguments;
clearTimeout(timeout);
timeout = setTimeout(function() { func.apply(context, args); }, wait);
};
}
$(document).on('click', '.acf-url-preview-fetch-btn', debounce(function(e) {
e.preventDefault();
var $btn = $(this);
var $status = $btn.siblings('.acf-url-preview-fetch-status');
var $block = $btn.closest('.acf-block-component, .acf-fields');
var url = $block.find('[data-name="source_url"] input').val();
if (!url) {
$status.text('Please enter a URL first').css('color', '#d63638');
return;
}
$btn.prop('disabled', true);
$status.text(acfUrlPreview.fetchingText).css('color', '#2271b1');
$.post(acfUrlPreview.ajaxUrl, {
action: 'acf_url_preview_fetch',
nonce: acfUrlPreview.fetchNonce,
url: url
}).done(function(response) {
if (!response.success || !response.data) {
$status.text(response.data || acfUrlPreview.errorText).css('color', '#d63638');
return;
}
var data = response.data;
if (data.title) $block.find('[data-name="preview_title"] input').val(data.title).trigger('change');
if (data.description) $block.find('[data-name="preview_description"] textarea').val(data.description).trigger('change');
if (data.image) $block.find('[data-name="external_image_url"] input').val(data.image).trigger('change');
if (data.title && !$block.find('[data-name="image_alt"] input').val()) {
$block.find('[data-name="image_alt"] input').val(data.title).trigger('change');
}
$status.text(acfUrlPreview.successText + ' ✓').css('color', '#00a32a');
}).fail(function() {
$status.text(acfUrlPreview.errorText).css('color', '#d63638');
}).always(function() {
$btn.prop('disabled', false);
setTimeout(function() { $status.text(''); }, 3000);
});
}, 300));
$(document).on('click', '.acf-url-preview-import-btn', debounce(function(e) {
e.preventDefault();
var $btn = $(this);
var $status = $btn.siblings('.acf-url-preview-import-status');
var $block = $btn.closest('.acf-block-component, .acf-fields');
var imageUrl = $block.find('[data-name="external_image_url"] input').val();
var editor = window.wp && wp.data ? wp.data.select('core/editor') : null;
var postId = $('#post_ID').val() || (editor ? editor.getCurrentPostId() : 0);
if (!imageUrl) {
$status.text('No external image URL to import').css('color', '#d63638');
return;
}
$btn.prop('disabled', true);
$status.text(acfUrlPreview.importingText).css('color', '#2271b1');
$.post(acfUrlPreview.ajaxUrl, {
action: 'acf_url_preview_import_image',
nonce: acfUrlPreview.importNonce,
image_url: imageUrl,
post_id: postId
}).done(function(response) {
if (response.success && response.data && response.data.attachment_id) {
var data = response.data;
var $imageField = $block.find('[data-name="local_image"]').first();
var field = window.acf && acf.getField ? acf.getField($imageField) : null;
var attachment = {
id: parseInt(data.attachment_id, 10),
url: data.preview_url || data.url || '',
alt: $block.find('[data-name="image_alt"] input').val() || ''
};
if (field && typeof field.render === 'function') {
field.render(attachment);
field.$input().trigger('change');
} else {
$imageField.find('input[type="hidden"]').first().val(String(attachment.id)).trigger('change');
$imageField.find('.acf-image-uploader').addClass('has-value');
$imageField.find('img').attr({ src: attachment.url, alt: attachment.alt });
}
$block.find('[data-name="image_source"] input[value="local"]').prop('checked', true).trigger('change');
$status.text(acfUrlPreview.successText).css('color', '#00a32a');
} else {
$status.text(response.data || acfUrlPreview.errorText).css('color', '#d63638');
}
}).fail(function() {
$status.text(acfUrlPreview.errorText).css('color', '#d63638');
}).always(function() { $btn.prop('disabled', false); });
}, 300));
})(jQuery);
